import re, datetime

now = apis.phone.get_current_date_and_time()
# parse date
for fmt in ['%A, %b %d, %Y','%A, %B %d, %Y']:
    try:
        d0 = datetime.datetime.strptime(now['date'], fmt).date(); break
    except Exception:
        pass
start = (d0 - datetime.timedelta(days=45))
end = (d0 + datetime.timedelta(days=45))
min_created_at = start.strftime('%Y-%m-%d')
max_created_at = end.strftime('%Y-%m-%d')

queries = [
    'check-in bag allowed weight',
    'checked baggage allowed weight',
    'allowed weight  kg',
    'baggage allowance  kg',
    'China flight baggage',
    'China check-in bag',
]

# helper to fetch all pages for a query

def fetch_all_threads(query):
    page_index = 0
    page_limit = 20
    out=[]
    while True:
        resp = apis.gmail.show_inbox_threads(access_token=gmail_token, query=query, min_created_at=min_created_at, max_created_at=max_created_at, page_index=page_index, page_limit=page_limit, sort_by='-updated_at')
        print('query',query,'page',page_index,'n',len(resp))
        if not resp:
            break
        out.extend(resp)
        page_index += 1
    return out

all_found=[]
for q in queries:
    threads = fetch_all_threads(q)
    # score by presence of key baggage phrases in subject+preview
    for t in threads:
        txt = (t.get('subject','')+' '+(t.get('preview') or '')).lower()
        if any(k in txt for k in ['allowed weight','check-in bag','checked baggage','baggage allowance','kg']):
            out = dict(t)
            out['query_used']=q
            all_found.append(out)
    print('query',q,'total_threads',len(threads),'baggage_like',sum(1 for t in threads if ( (t.get('subject','')+' '+(t.get('preview') or '')).lower().count('kg')>0 or 'allowed weight' in (t.get('subject','')+' '+(t.get('preview') or '')).lower() ) ))

print('total_candidate_threads_across_queries:',len(all_found))
# dedupe by email_thread_id
uniq={}
for t in all_found:
    uniq[t['email_thread_id']] = t
cands=list(uniq.values())
print('deduped_candidates:',len(cands))
# sort by updated_at

def dt_key(x):
    try:
        return datetime.datetime.fromisoformat(x['updated_at'].replace('Z','+00:00'))
    except Exception:
        return datetime.datetime.min
cands_sorted=sorted(cands,key=dt_key,reverse=True)
for t in cands_sorted[:10]:
    print('cand id',t['email_thread_id'],'updated_at',t.get('updated_at'),'subject',t.get('subject'),'from preview', (t.get('preview') or '')[:60])

# Extract allowed_kg by inspecting top few threads
allowed_kg=None
best_thread=None
max_kg=None
for t in cands_sorted[:5]:
    th=apis.gmail.show_thread(email_thread_id=t['email_thread_id'], access_token=gmail_token)
    full='\n'.join([e.get('body','') for e in th.get('emails',[])] + [d.get('body','') for d in th.get('drafts',[])])
    # capture patterns like 'allowed weight 26kg' or '1 check-in bag with allowed weight 26kg'
    found=[]
    for m in re.finditer(r'allowed weight\s*(\d+(?:\.\d+)?)\s*kg', full, flags=re.IGNORECASE):
        found.append(float(m.group(1)))
    # also other baggage patterns
    if not found:
        for m in re.finditer(r'check-?in bag[^\d]{0,40}(\d+(?:\.\d+)?)\s*kg', full, flags=re.IGNORECASE):
            found.append(float(m.group(1)))
    if not found:
        for m in re.finditer(r'checked baggage[^\d]{0,40}(\d+(?:\.\d+)?)\s*kg', full, flags=re.IGNORECASE):
            found.append(float(m.group(1)))
    if found:
        candidate=max(found)
        print('thread',t['email_thread_id'],'found_allowed',found,'max',candidate)
        if max_kg is None or candidate>max_kg:
            max_kg=candidate
            allowed_kg=candidate
            best_thread=t['email_thread_id']

print('FINAL allowed_kg:',allowed_kg,'best_thread:',best_thread,'max_kg',max_kg)

